import{c as n,Q as t,j as i,m as e}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"Kontrak Digital","description":"","frontmatter":{},"headers":[],"relativePath":"panduan/pppoe/kontrak.md","filePath":"panduan/pppoe/kontrak.md"}'),r={name:"panduan/pppoe/kontrak.md"};function l(s,a,o,k,d,g){return t(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="kontrak-digital" tabindex="-1">Kontrak Digital <a class="header-anchor" href="#kontrak-digital" aria-label="Permalink to &quot;Kontrak Digital&quot;">​</a></h1><p>eznom mendukung kontrak berlangganan digital — pelanggan dapat membaca dan menandatangani kontrak dari ponsel tanpa perlu temu fisik.</p><hr><h2 id="mengaktifkan-fitur-kontrak" tabindex="-1">Mengaktifkan Fitur Kontrak <a class="header-anchor" href="#mengaktifkan-fitur-kontrak" aria-label="Permalink to &quot;Mengaktifkan Fitur Kontrak&quot;">​</a></h2><ol><li>Buka <strong>Pengaturan → Kontrak</strong></li><li>Aktifkan opsi <strong>Wajibkan Tanda Tangan Kontrak</strong></li><li>Isi isi kontrak berlangganan di editor yang tersedia</li><li>Simpan</li></ol><p>Setelah diaktifkan, pelanggan baru perlu menandatangani kontrak sebelum layanan aktif.</p><hr><h2 id="alur-kontrak" tabindex="-1">Alur Kontrak <a class="header-anchor" href="#alur-kontrak" aria-label="Permalink to &quot;Alur Kontrak&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Operator tambah pelanggan</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Kirim link kontrak via WA/Email</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Pelanggan buka link → masukkan ID Pelanggan (verifikasi)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Pelanggan baca dokumen kontrak</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Pelanggan buka link tanda tangan</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Pelanggan tanda tangan digital (draw di layar)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Status kontrak: Ditandatangani ✓</span></span></code></pre></div><hr><h2 id="mengirim-link-kontrak" tabindex="-1">Mengirim Link Kontrak <a class="header-anchor" href="#mengirim-link-kontrak" aria-label="Permalink to &quot;Mengirim Link Kontrak&quot;">​</a></h2><p>Dari halaman <strong>Detail Pelanggan</strong>:</p><ol><li>Klik <strong>Kirim WA</strong> atau <strong>Kirim Email</strong> di header halaman</li><li>Pilih tipe notifikasi <strong>Link Kontrak</strong></li></ol><p>Pesan yang dikirim berisi dua link:</p><ul><li><strong>📄 Link Dokumen</strong> — pelanggan bisa membaca kontrak kapan saja</li><li><strong>✍️ Link Tanda Tangan</strong> — link bertanda tangan berlaku 7 hari, perlu diperbarui jika kedaluwarsa</li></ul><hr><h2 id="verifikasi-akses-dokumen" tabindex="-1">Verifikasi Akses Dokumen <a class="header-anchor" href="#verifikasi-akses-dokumen" aria-label="Permalink to &quot;Verifikasi Akses Dokumen&quot;">​</a></h2><p>Untuk melindungi privasi, pelanggan perlu memasukkan <strong>ID Pelanggan</strong> mereka sebelum bisa membaca dokumen kontrak. Jika ID tidak cocok, akses ditolak.</p><hr><h2 id="status-kontrak" tabindex="-1">Status Kontrak <a class="header-anchor" href="#status-kontrak" aria-label="Permalink to &quot;Status Kontrak&quot;">​</a></h2><p>Ditampilkan sebagai banner di halaman detail pelanggan:</p><table tabindex="0"><thead><tr><th>Status</th><th>Arti</th></tr></thead><tbody><tr><td>🟡 <strong>Menunggu TTD</strong></td><td>Link sudah dikirim, belum ditandatangani</td></tr><tr><td>🟢 <strong>Sudah Ditandatangani</strong></td><td>Pelanggan sudah menandatangani beserta waktu &amp; IP</td></tr></tbody></table><hr><h2 id="tanda-tangan-manual-admin" tabindex="-1">Tanda Tangan Manual (Admin) <a class="header-anchor" href="#tanda-tangan-manual-admin" aria-label="Permalink to &quot;Tanda Tangan Manual (Admin)&quot;">​</a></h2><p>Jika pelanggan tidak bisa menandatangani secara digital (misalnya sudah tanda tangan di atas kertas):</p><ol><li>Di halaman detail pelanggan, klik <strong>Tandai Sudah TTD</strong></li><li>Status kontrak berubah menjadi ditandatangani dengan keterangan <em>&quot;Manual oleh admin&quot;</em></li></ol><hr><h2 id="cetak-kontrak" tabindex="-1">Cetak Kontrak <a class="header-anchor" href="#cetak-kontrak" aria-label="Permalink to &quot;Cetak Kontrak&quot;">​</a></h2><p>Dari halaman detail pelanggan, klik <strong>Kontrak</strong> untuk membuka dokumen kontrak dalam tampilan siap cetak yang mencantumkan:</p><ul><li>Kop surat bisnis (nama, alamat, telepon, email)</li><li>Data pelanggan (nama, username, paket, tanggal pasang)</li><li>Isi kontrak</li><li>Tanda tangan digital (jika sudah ditandatangani)</li></ul><hr><h2 id="nomor-dokumen-kontrak" tabindex="-1">Nomor Dokumen Kontrak <a class="header-anchor" href="#nomor-dokumen-kontrak" aria-label="Permalink to &quot;Nomor Dokumen Kontrak&quot;">​</a></h2><p>Anda dapat men-generate nomor dokumen otomatis untuk setiap kontrak:</p><ol><li>Di halaman detail pelanggan (banner kontrak), klik <strong>+ Generate Nomor Dokumen</strong></li><li>Nomor akan digenerate secara unik dan tercantum di dokumen kontrak</li></ol><hr><h2 id="override-per-pelanggan" tabindex="-1">Override Per-Pelanggan <a class="header-anchor" href="#override-per-pelanggan" aria-label="Permalink to &quot;Override Per-Pelanggan&quot;">​</a></h2><p>Secara default, wajib kontrak mengikuti pengaturan global. Anda bisa override per-pelanggan:</p><ol><li>Di banner kontrak halaman detail, klik tombol <strong>Ikut Global / Override: Wajib / Override: Bebas</strong></li><li>Pilih opsi yang sesuai untuk pelanggan tersebut</li></ol>`,38)])])}const m=n(r,[["render",l]]);export{u as __pageData,m as default};
